assign wrapped = $signed(acc_data) + bias;

assign post_config_ready = !rst && !configured && !pending && (result_index == 2'b00);
assign acc_data_ready = !rst && configured && !post_config_valid && (!pending || result_data_ready);
assign result_data_valid = pending && !rst;
assign result_data = pending ? result_reg : 32'b0;

always @(posedge clk) begin
    if (rst) begin
        config_reg <= 65'b0;
        configured <= 0;
        result_index <= 2'b00;
        result_reg <= 32'b0;
        pending <= 0;
    end else begin
        if (post_config_valid && post_config_ready) begin
            config_reg <= post_config;
            configured <= 1;
            result_index <= 2'b00;
            pending <= 0;
        end else if (acc_data_valid && acc_data_ready) begin
            if (config_reg[0] && (wrapped[31] == 1'b1)) begin
                result_reg <= 32'b0;
            end else begin
                result_reg <= wrapped;
            end
            pending <= 1;
            if (result_index == 2'b11) begin
                configured <= 1'b0;
                result_index <= 2'b00;
            end else begin
                result_index <= result_index + 2'd1;
            end
        end else if (result_data_valid && result_data_ready && pending) begin
            pending <= 0;
        end
    end
end

endmodule

module hullcirq_npu2_fifo (
    input wire clk,
    input wire rst,
    input wire signed [31:0] result_data,
    input wire result_data_valid,
    output wire result_data_ready,
    output wire signed [31:0] output_data,
    output wire output_data_valid,
    input wire output_data_ready,
    output wire output_transfer
);

reg [31:0] storage [1:0];
reg read_ptr;
reg write_ptr;
reg [1:0] count;

assign output_data_valid = count != 2'd00 && !rst;
assign output_data = count != 2'd00 ? storage[read_ptr] : 32'b0;
assign output_transfer = output_data_valid && output_data_ready;
assign result_data_ready = !rst && ((count < 2'd2) || (output_data_valid && output_data_ready));

always @(posedge clk) begin
    if (rst) begin
        read_ptr <= 1'b0;
        write_ptr <= 1'b0;
        count <= 2'd00;
    end else begin
        if (result_data_valid && result_data_ready) begin
            storage[write_ptr] <= result_data;
            write_ptr <= ~write_ptr;
        end
        if (output_data_valid && output_data_ready) read_ptr <= ~read_ptr;
        case ({result_data_valid && result_data_ready, output_data_valid && output_data_ready})
            2'b10: count <= count + 2'd1;
            2'b01: count <= count - 2'd1;
            default: count <= count;
        endcase
    end
end

endmodule

