    send_load(13'h12fd);
    send_load(13'h1305);
    send_load(13'h1402);
    send_load(13'h1507);
    @(negedge clk); config_data=69'h1fffffffc000000063; config_data_valid=1;
    begin : config_wait
      for(i=0;i<2000;i=i+1) begin
        @(posedge clk);
        if(config_data_ready===1'b1) begin
          @(negedge clk); config_data_valid=0; disable config_wait;
