module hullcirq_npu2_control (
    input wire clk,
    input wire rst,
    input wire [68:0] config_data,
    input wire config_data_valid,
    output wire config_data_ready,
    output wire [3:0] schedule_config,
    output wire schedule_config_valid,
    input wire schedule_config_ready,
    output wire [64:0] post_config,
    output wire post_config_valid,
    input wire post_config_ready,
    input wire output_transfer,
    output wire busy,
    output wire job_done
);

localparam IDLE = 2'b00, SEND = 2'b01, RUN = 2'b10, DONE = 2'b11;
reg [1:0] state;
reg [68:0] saved_config;
reg schedule_sent;
reg post_sent;
reg [2:0] output_count;

assign config_data_ready = ~rst & (state == IDLE) & (config_data[3:0] >= 4'd1) & (config_data[3:0] <= 4'd8);
assign schedule_config = saved_config[3:0];
assign schedule_config_valid = ~rst & (state == SEND) & ~schedule_sent;
assign post_config = saved_config[68:4];
assign post_config_valid = ~rst & (state == SEND) & ~post_sent;
assign busy = ~rst & (state != IDLE);
assign job_done = ~rst & (state == DONE);

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        saved_config <= 69'b0;
        schedule_sent <= 1'b0;
        post_sent <= 1'b0;
        output_count <= 3'b0;
    end else begin
        case (state)
            IDLE: begin
                if (config_data_valid && config_data_ready) begin
                    saved_config <= config_data;
                    schedule_sent <= 1'b0;
                    post_sent <= 1'b0;
                    output_count <= 3'b0;
                    state <= SEND;
                end
            end
            SEND: begin
                if (schedule_config_valid && schedule_config_ready)
                    schedule_sent <= 1'b1;
                if (post_config_valid && post_config_ready)
                    post_sent <= 1'b1;
                if ((schedule_sent || (schedule_config_valid && schedule_config_ready)) &&
                    (post_sent || (post_config_valid && post_config_ready)))
                    state <= RUN;
            end
            RUN: begin
                if (output_transfer) begin
                    output_count <= output_count + 1'b1;
                    if (output_count == 3'd3) begin
                        state <= DONE;
                    end
                end
            end
            DONE: begin
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module hullcirq_npu2_buffer (
    input wire clk,
    input wire rst,
    input wire [12:0] load_data,
    input wire load_data_valid,
    output wire load_data_ready,
    input wire [2:0] read_index,
    input wire read_index_valid,
    output wire read_index_ready,
    output wire [31:0] operands,
    output wire operands_valid,
    input wire operands_ready
);

reg [7:0] bank_A [0:15];
reg [7:0] bank_B [0:15];
reg [31:0] response;
reg pending;

assign load_data_ready = !rst && !pending;
assign read_index_ready = !rst && !pending && !load_data_valid;
assign operands_valid = pending && !rst;
assign operands = pending ? response : 32'b0;

always @(posedge clk) begin
    if (rst) begin
        pending <= 0;
        response <= 32'b0;
    end else begin
        if (load_data_valid && load_data_ready) begin
            if (load_data[12]) begin
                bank_B[load_data[11:8]] <= load_data[7:0];
            end else begin
                bank_A[load_data[11:8]] <= load_data[7:0];
            end
            pending <= 0;
        end else if (read_index_valid && read_index_ready) begin
            response <= {bank_B[read_index * 2 + 1], bank_B[read_index * 2], bank_A[read_index + 8], bank_A[read_index]};
            pending <= 1;
        end
        if (pending && operands_ready) begin
            pending <= 0;
        end
    end
end

endmodule

module hullcirq_npu2_scheduler (
    input wire clk,
    input wire rst,
    input wire [3:0] schedule_config,
    input wire schedule_config_valid,
    output wire schedule_config_ready,
    output wire [2:0] read_index,
    output wire read_index_valid,
    input wire read_index_ready,
    input wire [31:0] operands,
    input wire operands_valid,
    output wire operands_ready,
    output wire [33:0] batch_data,
    output wire batch_data_valid,
    input wire batch_data_ready
);

reg [1:0] phase;
reg [3:0] saved_K;
reg [2:0] current_k;
reg [31:0] captured_operands;

assign schedule_config_ready = !rst && phase == 2'b00 && schedule_config >= 4'd1 && schedule_config <= 4'd8;
assign read_index = current_k;
assign read_index_valid = !rst && phase == 2'b01;
assign operands_ready = !rst && phase == 2'b10;
assign batch_data_valid = !rst && phase == 2'b11;

always @(posedge clk) begin
    if (rst) begin
        phase <= 2'b00;
        saved_K <= 4'b0000;
        current_k <= 3'b000;
        captured_operands <= 32'b0;
    end else begin
        case (phase)
            2'b00: begin
                if (schedule_config_valid && schedule_config_ready && schedule_config >= 4'b0001 && schedule_config <= 4'b1000) begin
                    saved_K <= schedule_config;
                    current_k <= 3'b000;
                    phase <= 2'b01;
                end
            end
            2'b01: begin
                if (read_index_ready) begin
                    phase <= 2'b10;
                end
            end
            2'b10: begin
                if (operands_valid && operands_ready) begin
                    captured_operands <= operands;
                    phase <= 2'b11;
                end
            end
            2'b11: begin
                if (batch_data_ready) begin
                    if (current_k == saved_K - 1'b1) begin
                        phase <= 2'b00;
                    end else begin
                        current_k <= current_k + 1'b1;
                        phase <= 2'b01;
                    end
                end
            end
        endcase
    end
end

assign batch_data = {(current_k == saved_K - 1'b1), (current_k == 3'b000), captured_operands};

endmodule

module hullcirq_npu2_dispatcher (
    input wire clk,
    input wire rst,
    input wire [33:0] batch_data,
    input wire batch_data_valid,
    output wire batch_data_ready,
    output wire [17:0] pair00,
    output wire pair00_valid,
    input wire pair00_ready,
    output wire [17:0] pair01,
    output wire pair01_valid,
    input wire pair01_ready,
    output wire [17:0] pair10,
    output wire pair10_valid,
    input wire pair10_ready,
    output wire [17:0] pair11,
    output wire pair11_valid,
    input wire pair11_ready
);

reg [33:0] captured_batch;
reg pending;
reg [3:0] delivered;
wire [3:0] transfer_mask;

assign batch_data_ready = !rst && !pending;
assign pair00_valid = !rst && pending && !delivered[0];
assign pair01_valid = !rst && pending && !delivered[1];
assign pair10_valid = !rst && pending && !delivered[2];
assign pair11_valid = !rst && pending && !delivered[3];

assign transfer_mask = {pair11_valid && pair11_ready, pair10_valid && pair10_ready, pair01_valid && pair01_ready, pair00_valid && pair00_ready};

always @(posedge clk) begin
    if (rst) begin
        captured_batch <= 34'b0;
        pending <= 0;
        delivered <= 4'b0000;
    end else begin
        if (batch_data_valid && batch_data_ready) begin
            captured_batch <= batch_data;
            pending <= 1;
            delivered <= 4'b0000;
        end else if (pending) begin
            delivered <= delivered | transfer_mask;
            if ((delivered | transfer_mask) == 4'b1111) begin
                pending <= 1'b0;
            end
        end
    end
end

assign pair00 = {captured_batch[33], captured_batch[32], captured_batch[23:16], captured_batch[7:0]};
